using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
using AlpineQuestPort;
class CardTests {
 const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Check(bool value,string name){if(!value)throw new Exception(name);Console.WriteLine("PASS "+name);}
 static T Field<T>(object value,string name){return (T)value.GetType().GetField(name,Flags).GetValue(value);}
 static void Mouse(RoutePlot plot,string name,int x,int y){typeof(RoutePlot).GetMethod(name,Flags).Invoke(plot,new object[]{new MouseEventArgs(MouseButtons.Left,1,x,y,0)});}
 static void Shot(Control control,string file){using(var image=new Bitmap(control.Width,control.Height)){control.DrawToBitmap(image,control.ClientRectangle);image.Save(file);}}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var route=new Track{Name="Обзорный маршрут"};route.Points.Add(new GeoPoint(46.57,8.4));route.Points.Add(new GeoPoint(46.58,8.41));route.Points.Add(new GeoPoint(46.57,8.43));var profile=RouteTerrain.Create(route);for(int i=0;i<profile.Heights.Length;i++)profile.Heights[i]=150+30*Math.Sin(i*.1);var original=(double[])profile.Heights.Clone();
 using(var plot=new RoutePlot{Size=new Size(1100,600),Profile=profile,LiftMode=true}){bool added=false;plot.Pick+=picked=>added=true;Shot(plot,Path.Combine(root,"before.png"));var axes=Field<ProfileAxes>(plot,"axes");int x=(int)(axes.Plot.Left+axes.Plot.Width*.5),y=(int)axes.Y(190);Mouse(plot,"OnMouseDown",x,y);Mouse(plot,"OnMouseMove",x,y-20);Mouse(plot,"OnMouseUp",x,y-20);Mouse(plot,"OnMouseClick",x,y-20);Check(plot.SelectedIndex>=0&&plot.Lift>0&&!added,"height mode selects and lifts without creating unsolicited waypoint");plot.SetLift(75);var point=plot.RaisedPoint();Check(Math.Abs(point.Elevation.Value-profile.Heights[plot.SelectedIndex]-75)<1e-8,"absolute height equals DEM plus requested clearance");Check(profile.Heights.SequenceEqual(original),"lifting never modifies DEM profile");var document=new MapDocument();document.Waypoints.Add(point);string file=Path.Combine(root,"raised.gpx");MapFiles.SaveGpx(document,file);Check(Math.Abs(MapFiles.Load(file).Waypoints[0].Elevation.Value-point.Elevation.Value)<.01,"raised height persists through GPX round trip");Shot(plot,Path.Combine(root,"lifted-profile.png"));profile.Heights[plot.SelectedIndex]=double.NaN;Check(plot.RaisedPoint()==null,"missing DEM cannot produce invented absolute altitude");}
 using(var form=new MainForm(null,true,Path.Combine(root,"workspace"))){form.Size=new Size(1280,920);form.Show();Application.DoEvents();var map=Field<MapCanvas>(form,"map");map.Settings.Gpu=false;map.Document.Tracks.Add(route);map.Selected=route;typeof(MainForm).GetMethod("ShowObjectCard",Flags).Invoke(form,new object[]{route});var terrain=Field<TerrainProfile>(form,"cardProfile");for(int i=0;i<terrain.Heights.Length;i++)terrain.Heights[i]=150+30*Math.Sin(i*.1);Field<Label>(form,"cardStats").Text=RouteTerrain.Summary(terrain);Check(Field<Panel>(form,"objectCard").Visible,"route card is visible with map retained");Shot(form,Path.Combine(root,"route-card.png"));var point=new GeoPoint(48.664585,37.863433){Name="Точка обзора",Elevation=225};map.Document.Waypoints.Add(point);map.Selected=point;typeof(MainForm).GetMethod("ShowObjectCard",Flags).Invoke(form,new object[]{point});Check(Field<Panel>(form,"objectCard").Height<210,"point card uses compact layout");var timer=Field<Timer>(form,"cardTimer");typeof(Timer).GetMethod("OnTick",Flags).Invoke(timer,new object[]{EventArgs.Empty});Application.DoEvents();
Check(!Field<Label>(form,"cardSk").Text.Contains("EPSG"),"point card hides EPSG designation");
Check(Field<Label>(form,"cardSk").Text.Contains(form.CardCopyValue(point,1)),"card XY matches existing PROJ coordinate conversion");
Check(form.CardCopyValue(point,2)=="48.664585, 37.863433","WGS copy payload contains coordinate pair");Check(form.CardCopyValue(point,1)=="X = 5393052; Y = 7416392","SK42 copy payload contains XY without EPSG");Check(Field<Button>(form,"cardCopyWgs").Top>=Field<Label>(form,"cardWgs").Bottom&&Field<Button>(form,"cardCopySk").Top>=Field<Label>(form,"cardSk").Bottom,"copy buttons appear below each coordinate row");Shot(form,Path.Combine(root,"point-card.png"));form.Width=850;Application.DoEvents();
var card=Field<Panel>(form,"objectCard");var stats=Field<Label>(form,"cardStats");Check(stats.Bottom<=card.ClientSize.Height-card.Padding.Bottom,"narrow card retains coordinate and elevation rows");Shot(form,Path.Combine(root,"point-card-narrow.png"));form.Close();}
 Console.WriteLine("ALL CARD AND HEIGHT TESTS PASSED");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
